    </g>
    <g fill="#ff3fa4" opacity=".9"><rect x="1104" y="160" width="3" height="3"/><rect x="1044" y="182" width="3" height="3"/><rect x="1186" y="176" width="3" height="3"/><rect x="1253" y="190" width="3" height="3"/></g>
    <g fill="#35e6e0" opacity=".9"><rect x="1110" y="176" width="3" height="3"/><rect x="1048" y="204" width="3" height="3"/><rect x="1190" y="196" width="3" height="3"/><rect x="1126" y="210" width="3" height="3"/><rect x="1214" y="214" width="3" height="3"/></g>
    <path d="M0 250C140 200 260 205 400 245s280 40 420-10 270-50 420 0 140 22 200 5v180H0z" fill="url(#d1)"/>
