          <g fill="#35e6e0" opacity=".8"><rect x="12" y="8" width="20" height="11" rx="3"/><rect x="68" y="8" width="20" height="11" rx="3"/></g>
          <g fill="#ffb067" opacity=".9"><rect x="40" y="8" width="20" height="11" rx="3"/><rect x="124" y="8" width="16" height="11" rx="3"/></g>
        </g>
        <use href="#cr" x="156"/><use href="#cr" x="312"/><use href="#cr" x="468"/>
        <path d="M624 0h70c24 0 40 20 46 38H624z" fill="#ff5e4d"/>
