      </g>
    </g>
    <rect x="0" y="324" width="1440" height="4" fill="#140c1f"/>
    <path d="M0 336h1440" stroke="#ff3fa4" stroke-width="2" class="dash" opacity=".7"/>
    <path d="M0 350C200 320 380 330 560 352s330 24 520-6 260-20 360 4v70H0z" fill="url(#d3)"/>
    <!-- cacti -->
    <g fill="#0b0612"><rect x="140" y="330" width="10" height="70" rx="5"/><rect x="124" y="352" width="26" height="8" rx="4"/><rect x="124" y="340" width="8" height="20" rx="4"/><rect x="150" y="346" width="18" height="8" rx="4"/><rect x="160" y="334" width="8" height="20" rx="4"/>
    <rect x="1320" y="340" width="9" height="60" rx="4"/><rect x="1306" y="358" width="23" height="7" rx="3"/><rect x="1306" y="348" width="7" height="17" rx="3"/></g>
  </svg>

  <div class="wrap">
    <div class="hero-copy">
      <div class="eyebrow">Overnight Sleeper · Est. 1924</div>
      <h1>Sleep across the <em>desert.</em> Wake in neon.</h1>
      <p>Dune Line carries you 1,140 km from the silent sands of Amberwell to the electric skyline of Neon City — in eleven hours, under every star.</p>
      <div class="btns">
        <a href="#fares" class="btn primary">Reserve your berth →</a>
        <a href="#timetable" class="btn ghost">View departures</a>
      </div>
    </div>
  </div>
  <div class="hero-stats">
    <div class="wrap">
      <div class="stats">
        <div><strong>1,140 km</strong>Of open dune</div>
